// src/spec/specindex.ts -- `nen spec index`: `<root>/INDEX.md` regenerated
// from the feature folders' own spec.md headers, never edited by hand.
//
// A GENERATED FILE THAT CAN TELL A HAND EDIT FROM A STALE ONE. The first line
// of INDEX.md is a marker carrying the sha256 of every byte below it. When the
// body still hashes to the marker, the file is exactly what nen last wrote, and
// a newer folder makes it merely `stale` -- `--write` regenerates it. When the
// body does not hash to the marker, or there is no marker, someone edited it,
// and `--write` REFUSES: overwriting would destroy an edit nen cannot judge
// (drift refusal). Which of the two is right is the maintainer's to say.
//
// THE COLUMNS ARE THE HEADER'S, READ, NEVER INFERRED: Spec Kit's pinned
// template opens spec.md with `# Feature Specification: <title>` and
// `**Status**:` / `**Created**:` lines; the open-marker count is computed with
// the grammar every other spec verb uses. A folder with no readable spec.md is
// an error row, and the file is not written over it.

import { existsSync, lstatSync, readdirSync, readFileSync, realpathSync, statSync, writeFileSync } from "node:fs";
import { join, relative, isAbsolute } from "node:path";
import { markersIn, proseLines } from "./lines.js";
import { matchFolder, type SpecLayout } from "./layout.js";
import { sha256 } from "./check.js";

export const SPEC_INDEX_CONTRACT = "nen.spec.index/v0.1";
export const INDEX_MARKER_PREFIX = "<!-- generated by nen spec index; regenerate with 'nen spec index --write', never edit by hand · sha256:";

export type IndexState = "current" | "stale" | "hand-edited" | "absent";

export interface IndexRow {
  readonly nnn: string;
  readonly slug: string;
  readonly folder: string;
  readonly title: string | null;
  readonly status: string | null;
  readonly created: string | null;
  readonly openMarkers: number | null;
  readonly error: string | null;
}

/** KEY ORDER IS THE DOCUMENTED `--json` SHAPE. */
export interface SpecIndexReport {
  readonly contract: string;
  readonly repo: string;
  readonly layout: string;
  readonly path: string;
  readonly rows: readonly IndexRow[];
  /** Directories under the root whose names the layout does not match. */
  readonly ignored: readonly string[];
  readonly state: IndexState;
  readonly action: "none" | "written" | "would-write" | "refused";
  readonly reason: string | null;
}

const cell = (value: string | null): string => (value === null || value === "" ? "—" : value.replace(/\|/g, "\\|"));

function headerOf(text: string): Pick<IndexRow, "title" | "status" | "created" | "openMarkers"> {
  const lines = proseLines(text);
  const heading = lines.find((line): boolean => /^#\s+\S/.test(line.text))?.text.replace(/^#\s+/, "").trim() ?? null;
  const title = heading === null ? null : heading.replace(/^Feature Specification:\s*/i, "").trim() || null;
  const field = (name: string): string | null => {
    const found = lines.map((line): RegExpExecArray | null => new RegExp(`^\\s*\\*\\*${name}\\*\\*\\s*:\\s*(.*?)\\s*$`, "i").exec(line.text)).find((match): boolean => match !== null);
    return found?.[1]?.trim() || null;
  };
  const openMarkers = lines.reduce((sum, line): number => sum + markersIn(line.text).length, 0);
  return { title, status: field("Status"), created: field("Created"), openMarkers };
}

export function readRows(repo: string, layout: SpecLayout): { rows: IndexRow[]; ignored: string[] } {
  const rootPath = join(repo, layout.root);
  if (!existsSync(rootPath)) throw new Error(`${layout.root}/ does not exist under --repo; a layout whose root is missing is refused rather than read as an empty index`);
  const rows: IndexRow[] = [];
  const ignored: string[] = [];
  for (const entry of readdirSync(rootPath, { withFileTypes: true }).sort((a, b): number => a.name.localeCompare(b.name))) {
    if (!entry.isDirectory()) continue;
    const parsed = matchFolder(layout, entry.name);
    const folder = `${layout.root}/${entry.name}`;
    if (parsed === null) {
      ignored.push(folder);
      continue;
    }
    const specPath = join(rootPath, entry.name, "spec.md");
    let text: string | null = null;
    let error: string | null = null;
    try {
      text = statSync(specPath).isFile() ? readFileSync(specPath, "utf8") : null;
      if (text === null) error = `${folder}/spec.md is not a file`;
    } catch (caught) {
      error = (caught as NodeJS.ErrnoException).code === "ENOENT" ? `${folder}/spec.md does not exist` : `could not read ${folder}/spec.md: ${(caught as Error).message}`;
    }
    rows.push(text === null ? { ...parsed, folder, title: null, status: null, created: null, openMarkers: null, error } : { ...parsed, folder, ...headerOf(text), error: null });
  }
  rows.sort((a, b): number => a.nnn.localeCompare(b.nnn) || a.slug.localeCompare(b.slug));
  return { rows, ignored };
}

export function renderIndexBody(rows: readonly IndexRow[]): string {
  return [
    "# Feature index",
    "",
    "| # | Slug | Title | Status | Created | Open markers |",
    "|---|---|---|---|---|---|",
    ...rows.map((row): string => `| ${row.nnn} | [\`${row.slug}\`](${row.folder.split("/").slice(-1)[0] ?? row.slug}/spec.md) | ${cell(row.title)} | ${cell(row.status)} | ${cell(row.created)} | ${row.openMarkers ?? "—"} |`),
    "",
  ].join("\n");
}

export function renderIndexFile(rows: readonly IndexRow[]): string {
  const body = renderIndexBody(rows);
  return `${INDEX_MARKER_PREFIX}${sha256(body)} -->\n${body}`;
}

/** What the INDEX.md on disk is, against what would be generated now. */
export function indexState(existing: string | null, generated: string): IndexState {
  if (existing === null) return "absent";
  const normalized = existing.replace(/\r\n/g, "\n");
  const newline = normalized.indexOf("\n");
  const first = newline === -1 ? normalized : normalized.slice(0, newline);
  const body = newline === -1 ? "" : normalized.slice(newline + 1);
  if (!first.startsWith(INDEX_MARKER_PREFIX) || !first.endsWith(" -->")) return "hand-edited";
  const recorded = first.slice(INDEX_MARKER_PREFIX.length, -" -->".length);
  if (recorded !== sha256(body)) return "hand-edited";
  return normalized === generated ? "current" : "stale";
}

export function specIndex(repo: string, layout: SpecLayout, options: { readonly write: boolean; readonly dryRun: boolean }): SpecIndexReport {
  const { rows, ignored } = readRows(repo, layout);
  const relativePath = `${layout.root}/INDEX.md`;
  const path = join(repo, relativePath);
  let existing: string | null = null;
  if (lstatSync(path, { throwIfNoEntry: false })?.isFile() === true) existing = readFileSync(path, "utf8");
  else if (lstatSync(path, { throwIfNoEntry: false }) !== undefined) throw new Error(`${relativePath} is not a regular file (a link or a directory); nen reads and writes no index through one`);
  const generated = renderIndexFile(rows);
  const state = indexState(existing, generated);
  const base = { contract: SPEC_INDEX_CONTRACT, repo, layout: layout.pattern, path: relativePath, rows, ignored, state };
  const errors = rows.filter((row): boolean => row.error !== null);
  if (!options.write) return { ...base, action: "none", reason: null };
  if (errors.length > 0) return { ...base, action: "refused", reason: `${errors.length} folder(s) have no readable spec.md; the index is not written over a folder it cannot read` };
  if (state === "hand-edited") return { ...base, action: "refused", reason: `${relativePath} was edited by hand (its body does not hash to its marker, or it has none); nen will not overwrite an edit it cannot judge` };
  if (state === "current") return { ...base, action: "none", reason: null };
  // THE WRITE STAYS IN THE REPOSITORY: a root that is a link out would carry
  // it elsewhere, so it is refused rather than followed (an INDEX.md that is
  // a link was already refused at the read above).
  const inside = relative(realpathSync(repo), realpathSync(join(repo, layout.root)));
  if (inside === "" || inside.startsWith("..") || isAbsolute(inside)) return { ...base, action: "refused", reason: `${layout.root}/ resolves outside --repo; nen writes no index through a link` };
  if (options.dryRun) return { ...base, action: "would-write", reason: null };
  writeFileSync(path, generated);
  return { ...base, action: "written", reason: null };
}

export function renderSpecIndex(report: SpecIndexReport): string[] {
  return [
    `${report.path}: ${report.state} · action ${report.action}${report.reason === null ? "" : ` -- ${report.reason}`}`,
    ...report.rows.map((row): string => `  ${row.nnn} ${row.slug} ${row.error ?? `${row.status ?? "—"} · ${row.openMarkers ?? 0} open marker(s) · ${row.title ?? "(no title)"}`}`),
    ...report.ignored.map((folder): string => `  ignored ${folder} (does not match ${report.layout})`),
  ];
}
